// Defines the task time in [ms] milliseconds, normally 10 - 50 ms
#define DEM_TASK_TIME            20u

// Defines the maximum valu for fault counter
#define DEM_JDD_CUSTOM_FAULT_CNT_MAX            255u

// Defines the maximum value of the aging counter, set to this value in case of failed test
#define AGING_COUNTER_MAX        40u

// Defines the maximum event ID from the table below. SET THIS CORRECTLY!!!
#define DEM_MAX_EVENT_ID        (uint16)DEM_CONFIG_ENTRY_MAX


/******************************************************************************
* C A L L B A C K   F U N C T I O N   D E C L A R A T I O N
*
* Declare all callback functions here
*
* condition_passed
* This handler is called when a 'passed' event occurs. Any further error processing
* takes only place if the handler returns 'true'
* boolean condition_passed_handler(uint16 event_id);
*
* condition_failed
* This handler is called when a 'failed' event occurs. Any further error processing
* takes only place if the handler returns 'true'
* boolean condition_failed_handler(uint16 event_id);
*
* notify_passed
* This handler is called when a event id is set to 'passed' state
* 'status_passed' is set to 'true'
* boolean notify_passed_handler(uint16 event_id, boolean status_passed);
*
* notify_failed
* This handler is called when a event id is set to 'failed' state
* 'status_passed' is set to 'false'
* boolean condition_failed_handler(uint16 event_id, boolean status_passed);
*
* notify_custom
* This handler is used as custom error memory notification
* define the function in cust like:
* void ErrCustLog(uint16 event_id, uint8 status);
* the status flags are any combination of:
* DEM_STATUS_TEST_FAILED
* DEM_STATUS_TEST_FAILED_THIS_CYCLE
* DEM_STATUS_PENDING_DTC
* DEM_STATUS_CONFIRMED_DTC
* DEM_STATUS_TEST_NOT_COMPLETED_SINCE_CLEAR
* DEM_STATUS_TEST_FAILED_SINCE_CLEAR
* DEM_STATUS_TEST_NOT_COMPLETED_THIS_CYCLE
*
******************************************************************************/

